public interface INotifier
    {
        void Notify(string message);
    }

public class Manager : INotifier
    {
        public void Run()
        {
            Console.WriteLine("Manager starting work...");
            IEnumerable<IWorker> workers = WorkerFactory.CreateWorkers(this);

            // one-to-many: Manager invokes all workers
            foreach (var worker in workers)
            {
                worker.Process();
            }
        }

        // many-to-one: workers call back here
        public void Notify(string message)
        {
            Console.WriteLine($"Manager received notification: {message}");
        }
    }

class Program
    {
        static void Main(string[] args)
        {
            Manager manager = new Manager();
            manager.Run();
            Console.WriteLine("All work completed. Press any key to exit.");
            Console.ReadKey();
        }
    }

public static class Helper
    {
        public static string FormatMessage(string workerName, string text)
        {
            return $"[{workerName}] {text}";
        }
    }

public class WorkerC : IWorker
    {
        private readonly INotifier _notifier;

        public WorkerC(INotifier notifier)
        {
            _notifier = notifier;
        }

        public void Process()
        {
            string msg = Utilities.Helper.FormatMessage("WorkerC", "Hi there, C here");
            System.Console.WriteLine(msg);
            _notifier.Notify("WorkerC has finished processing.");
        }
    }

public static class WorkerFactory
    {
        public static IEnumerable<IWorker> CreateWorkers(INotifier notifier)
        {
            // create multiple workers, each knows how to call back
            return new List<IWorker>
            {
                new WorkerA(notifier),
                new WorkerB(notifier),
                new WorkerC(notifier)
            };
        }
    }
